with q as (
 select * from (values
 ('pcac-2026-legislacao-lei-organica-nacional-14735','pcac-nat-vetos-01','Lei nº 14.735/2023 — promulgação dos vetos','Para estudar a Lei Orgânica Nacional das Polícias Civis, qual texto deve ser considerado após a rejeição de vetos pelo Congresso em junho de 2024?','(A) Apenas a publicação original de novembro de 2023.\n(B) O texto atualizado, considerando as partes vetadas posteriormente promulgadas e distinguindo os vetos mantidos.\n(C) Somente a lei estadual de cada unidade federativa.\n(D) O texto original, sem qualquer alteração.\n(E) Apenas os dispositivos regulamentados por decreto.','B','A lei deve ser estudada em seu texto atualizado, que incorpora as partes vetadas promulgadas em junho de 2024, sem tratar como vigentes os dispositivos cujos vetos foram mantidos.'),
 ('pcac-2026-legislacao-lei-organica-nacional-14735','pcac-nat-competencia-02','Lei nº 14.735/2023 — normas gerais e suplementação','Segundo o art. 3º da Lei nº 14.735/2023, a legislação estadual sobre a Polícia Civil:','(A) É proibida após a edição da lei nacional.\n(B) Pode detalhar matérias específicas e suplementar as normas nacionais, respeitados os limites constitucionais.\n(C) Pode contrariar livremente as normas gerais nacionais.\n(D) Só pode tratar de remuneração.\n(E) Depende sempre de autorização do Senado.','B','O art. 3º reserva à lei orgânica estadual regras específicas e admite legislação suplementar, observados os limites constitucionais e as normas gerais nacionais.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-pccr-526-01','LC nº 526/2026 — curso de formação','Conforme a nova redação do art. 65, § 2º, da LC nº 129/2004, o que marca o início imediato do curso específico de formação policial?','(A) A publicação do resultado final do concurso.\n(B) A convocação para investigação social.\n(C) O ato coletivo de investidura.\n(D) A conclusão do estágio probatório.\n(E) A primeira lotação definitiva.','C','A LC nº 526/2026 prevê que o ato coletivo de investidura marca o início imediato do curso específico de formação, frequentado pelo servidor na condição de servidor público em efetivo exercício.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-pccr-496-02','LC nº 496/2025 — unificação dos cargos','Qual alteração foi promovida pela LC nº 496/2025 na estrutura dos cargos da Polícia Civil do Acre?','(A) Extinguiu o cargo de Delegado.\n(B) Unificou os cargos de agente e escrivão sob a nomenclatura Oficial Investigador de Polícia.\n(C) Transformou todos os cargos em peritos.\n(D) Criou dois cargos separados de Oficial Investigador.\n(E) Revogou integralmente a Lei nº 3.228/2017.','B','A LC nº 496/2025 unificou os cargos de agente e escrivão sob a nomenclatura Oficial Investigador de Polícia e manteve a estrutura de carreira da Lei nº 3.228/2017.')
 ) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation)
